CREATE TABLE IF NOT EXISTS rm_workspace_auth_telemetry_events (
 id INTEGER PRIMARY KEY, endpoint TEXT NOT NULL CHECK(endpoint IN ('sign-in-email','send-verification-email','verify-email','request-password-reset','reset-password','sign-out','revoke-session','revoke-other-sessions','two-factor-enable','two-factor-verify')), outcome TEXT NOT NULL CHECK(outcome IN ('attempted','accepted','rejected','unknown')), user_id TEXT REFERENCES "user"(id), session_id TEXT, identity_hash TEXT CHECK(identity_hash IS NULL OR length(identity_hash)=64), identity_key_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS rm_workspace_auth_state_events (
 id INTEGER PRIMARY KEY, state_transition TEXT NOT NULL CHECK(state_transition IN ('email_verified','mfa_enabled','credential_updated','session_created','session_deleted')), user_id TEXT REFERENCES "user"(id), session_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER IF NOT EXISTS rm_workspace_auth_telemetry_events_no_update BEFORE UPDATE ON rm_workspace_auth_telemetry_events BEGIN SELECT RAISE(ABORT, 'workspace auth telemetry events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS rm_workspace_auth_telemetry_events_no_delete BEFORE DELETE ON rm_workspace_auth_telemetry_events BEGIN SELECT RAISE(ABORT, 'workspace auth telemetry events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS rm_workspace_auth_state_events_no_update BEFORE UPDATE ON rm_workspace_auth_state_events BEGIN SELECT RAISE(ABORT, 'workspace auth state events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS rm_workspace_auth_state_events_no_delete BEFORE DELETE ON rm_workspace_auth_state_events BEGIN SELECT RAISE(ABORT, 'workspace auth state events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS rm_auth_evidence_email_verified AFTER UPDATE OF emailVerified ON "user" WHEN COALESCE(OLD.emailVerified,0)=0 AND NEW.emailVerified=1 BEGIN INSERT INTO rm_workspace_auth_state_events(state_transition,user_id) VALUES('email_verified',NEW.id); END;
CREATE TRIGGER IF NOT EXISTS rm_auth_evidence_credential_updated AFTER UPDATE OF password ON "account" WHEN OLD.password IS NOT NEW.password BEGIN INSERT INTO rm_workspace_auth_state_events(state_transition,user_id) VALUES('credential_updated',NEW.userId); END;
CREATE TRIGGER IF NOT EXISTS rm_auth_evidence_session_created AFTER INSERT ON "session" BEGIN INSERT INTO rm_workspace_auth_state_events(state_transition,user_id,session_id) VALUES('session_created',NEW.userId,NEW.id); END;
CREATE TRIGGER IF NOT EXISTS rm_auth_evidence_session_deleted AFTER DELETE ON "session" BEGIN INSERT INTO rm_workspace_auth_state_events(state_transition,user_id,session_id) VALUES('session_deleted',OLD.userId,OLD.id); END;
